import openpyxl, re

def normalize_dtc_code_text(value):
    text = re.sub(r'\s+', '', value or '').upper()
    if text.startswith('0X'): text = text[2:]
    return text.replace('-', '')

def is_hex_text(value):
    return bool(value) and all((c in '0123456789ABCDEF') for c in value)

def try_j2012_to_raw_hex(dtc_code):
    text = normalize_dtc_code_text(dtc_code)
    if len(text) == 7 and text[0] in 'PCBU' and is_hex_text(text[1:]):
        letter_idx = 'PCBU'.index(text[0])
        d1 = int(text[1], 16) & 0x03
        d2 = int(text[2], 16) & 0x0F
        b1 = (letter_idx << 6) | (d1 << 4) | d2
        return f'{b1:02X}{text[3:7]}'
    if len(text) == 6 and is_hex_text(text):
        return text
    return None

def get_dtc_key_candidates(dtc_code):
    candidates = []
    def add(k):
        if k and k not in candidates: candidates.append(k)
    normalized = normalize_dtc_code_text(dtc_code)
    add(normalized)
    raw_hex = try_j2012_to_raw_hex(normalized)
    if raw_hex: add(raw_hex)
    if len(normalized) > 2:
        base_code = normalized[:-2]
        add(base_code)
        add(base_code + '00')
        add(base_code + '-00')
    if raw_hex and len(raw_hex) > 2:
        base_hex = raw_hex[:-2]
        add(base_hex)
        add(base_hex + '00')
    return candidates

def add_dtc_dictionary_key(d, raw_code, name):
    code = normalize_dtc_code_text(raw_code)
    if not code: return
    for key in get_dtc_key_candidates(code):
        if key not in d: d[key] = name
    if is_hex_text(code) and 0 < len(code) < 6:
        padded = code.zfill(6)
        for key in get_dtc_key_candidates(padded):
            if key not in d: d[key] = name

