"        private byte GetCurrentStatusMask()
        {
            if (cbStatusMask?.SelectedItem is ComboBoxItem selectedItem && selectedItem.Tag != null)
            {
                try { return Convert.ToByte(selectedItem.Tag.ToString().Replace("0x", ""), 16); }
                catch { return 0x09; }
            }
            return 0x09;
        }

        private static string NormalizeSnapshotOrder(string snapshot)
        {
            if (string.IsNullOrWhiteSpace(snapshot)) return snapshot;
            var L = LocalizationManager.Instance;
            string recLabel = L["dtc.received"];
            string transLabel = L["dtc.transmitted"];

            int recIdx = snapshot.IndexOf(recLabel + ":", StringComparison.OrdinalIgnoreCase);
            int transIdx = snapshot.IndexOf(transLabel + ":", StringComparison.OrdinalIgnoreCase);

            if (recIdx >= 0 && transIdx >= 0 && recIdx < transIdx)
            {
                string recPart = snapshot.Substring(recIdx, transIdx - recIdx).Trim();
                string transPart = snapshot.Substring(transIdx).Trim();
                return transPart + "\n\n" + recPart;
            }
            return snapshot;
